output_text:
[
  {
    "id": "no_cart_single_file_shelf_aisle",
    "text": "Shopping carts are forbidden in one-cell-wide shelf aisles where the shopper is between shelves.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFile",
            "betweenShelves"
          ]
        },
        "cartInSingleFileShelfAisle": {
          "and": [
            "hasCart",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartInSingleFileShelfAisle"
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "A shopper may not move into a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFile",
            "betweenShelves"
          ]
        },
        "moveAction": {
          "or": [
            "N",
            "S",
            "E",
            "W",
            "MOVE"
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "moveAction",
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileShelfAisleWithCart"
    }
  },
  {
    "id": "park_before_pedestrian_aisle",
    "text": "On arriving with a cart at the mouth of a pedestrian-only shelf aisle, the shopper is obliged to park the cart before entering further.",
    "abstraction": {
      "state_properties": {
        "pedestrianAisleMouth": "at(6,3)",
        "moveNorth": "N"
      },
      "events": {
        "arriveAtPedestrianAisleMouthWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "moveNorth"
            ]
          },
          "post": {
            "and": [
              "pedestrianAisleMouth",
              "hasCart"
            ]
          }
        },
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arriveAtPedestrianAisleMouthWithCart",
      "discharge": "dropCart"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks or releases a cart, they are obliged to retrieve a cart again before leaving the store.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickupCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCart",
      "discharge": "pickupCart"
    }
  },
  {
    "id": "park_cart_only_in_wide_non_shelf_area",
    "text": "Carts may only be parked in wide non-shelf areas, not beside merchandise or inside constricted aisles.",
    "abstraction": {
      "state_properties": {
        "wideArea": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "nonShelfArea": {
          "not": "adjShelf"
        },
        "safeCartParkingArea": {
          "and": [
            "wideArea",
            "nonShelfArea"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "safeCartParkingArea"
          }
        ]
      }
    }
  },
  {
    "id": "cart_shelf_interaction_only_from_main_aisle",
    "text": "When using a cart, shoppers should interact with shelves only from a main horizontal aisle, not from the side of a shelf.",
    "abstraction": {
      "state_properties": {
        "sideFacingShelf": {
          "or": [
            "shelfE",
            "shelfW"
          ]
        },
        "cartShelfInteractionFromSide": {
          "and": [
            "hasCart",
            "INTERACT",
            "adjShelf",
            "sideFacingShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartShelfInteractionFromSide"
    }
  },
  {
    "id": "wide_shelf_interaction_requires_cart",
    "text": "Shelf interactions from wide aisles require the shopper to have a cart, while hand-carrying is allowed only in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "wideShelfFrontage": {
          "and": [
            "adjShelf",
            {
              "not": "singleFile"
            }
          ]
        },
        "cartlessWideShelfInteraction": {
          "and": [
            "INTERACT",
            "wideShelfFrontage",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartlessWideShelfInteraction"
    }
  },
  {
    "id": "north_without_cart_only_in_pedestrian_aisle",
    "text": "Moving north without a cart is forbidden except when entering or traversing the pedestrian-only single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFile",
            "betweenShelves"
          ]
        },
        "pedestrianAisleMouth": "at(6,3)",
        "singleFileAccessArea": {
          "or": [
            "singleFileShelfAisle",
            "pedestrianAisleMouth"
          ]
        },
        "northWithoutCartOutsidePedestrianAisle": {
          "and": [
            "N",
            {
              "not": "hasCart"
            },
            {
              "not": "singleFileAccessArea"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "northWithoutCartOutsidePedestrianAisle"
    }
  }
]
